/* Química A01 · Objetivos e ramos da química; método científico. Conferido em Python:
   oxigênio preso por grama de ferro que vira Fe₂O₃: 3·15,999/(2·55,845) = 0,4297 → 0,43 g/g (Fe₃O₄ daria 0,38);
   modelo do laboratório: t = 60 s · 2^(−(T−25)/10) · N^(−1/3): 25 °C inteiro 60 s; 35 °C 30 s; 15 °C 120 s; 8 pedaços 30 s; pó (64) 15 s;
   exemplo 1: médias 60 s e 30 s, variação −50% (outras variações: 50 → 40 s, −20%; 80 → 60 s, −25%); exemplo 2: 254,00 − 253,48 = 0,52 g;
   exemplo 3: 5,00 → 5,86 g: 0,86 g de O, 2,00 g de Fe, 40%;
   exercícios: 5) média 41 s; 6) 0,52 g; 9) 1,29/0,43 = 3,00 g; 10) 80 → 40 → 20 → 10 s; 12) 25%; 14) 0,35 g; 15) 320,00 − 5·0,50 = 317,50 g;
   17) 0,645/0,43 = 1,50 g = 25% de 6,00 g; 18) 3,00 + 8,00 = 11,00 g;
   chefão (2,00 L; ar 1,20 g/L; O₂ 23% da massa e 1,33 g/L): ar 2,40 g, O₂ 0,552 g; 1,00 g de Fe ganha 0,43 g; volume de O₂ gasto 0,3233 L;
   ar que entra 0,388 g → 612,39 g; ferro máximo 1,284 g (25,7% de 5,00 g); fração do ar em volume 20,75%; frasco de 4,00 L: 1,104 g de O₂, 2,567 g de Fe (51,3%);
   ponte: 12 g de C queimando liberam 393,5 kJ → Δm = E/c² = 4,4 × 10⁻¹² kg (4 ng em 44 g de CO₂). */
F.registrar("quimica/A01", {
  retoma: [],
  html(F) {
    const R = String.raw;
    const fig = (conteudo, h = 170) => D.svg(560, h, conteudo, "figura");
    /* balança digital com o prato em y = 128; o = {frasco, tampa, bolhas, gas, palha, rot, nivel, cor} */
    const palha = (x, y, cor) => [0, 1, 2, 3].map((k) => `<path d="M${x - 24} ${y - 3 - k * 5} q5 ${-14 + k * 2} 11 -3 q6 12 11 -4 q5 -13 11 1 q4 9 9 -3" style="fill:none;stroke:${cor};stroke-width:1.6"/>`).join("");
    const balanca = (x, leit, o = {}) => {
      const b = 128;
      let s = `<rect x="${x - 60}" y="${b + 6}" width="120" height="30" rx="5" style="fill:var(--card2);stroke:var(--ink3);stroke-width:1.5"/><rect x="${x - 48}" y="${b}" width="96" height="6" rx="2" style="fill:var(--ink3)"/><rect x="${x - 40}" y="${b + 11}" width="80" height="20" rx="4" style="fill:var(--bg);stroke:var(--line)"/>` + D.txt(x, b + 26, leit, "tx", "middle", 'style="font-weight:700"');
      if (o.frasco !== false && !o.palha) {
        s += D.copo(x - 30, b - 76, 60, 76, o.nivel ?? 0.55, o.cor || "var(--mA)");
        if (o.tampa) s += `<rect x="${x - 35}" y="${b - 86}" width="70" height="11" rx="3" style="fill:var(--ink3)"/>`;
        if (o.bolhas) s += [[-14, 20], [3, 34], [15, 14], [-4, 9], [9, 26]].map(([dx, dy]) => `<circle cx="${x + dx}" cy="${b - dy}" r="2.6" style="fill:none;stroke:var(--ink);stroke-width:1.1"/>`).join("") + `<ellipse cx="${x}" cy="${b - 5}" rx="10" ry="3.5" style="fill:var(--ink)"/>`;
        if (o.gas) s += D.seta(x, b - 80, x, b - 100, "var(--warn)", 1.8) + D.txt(x + 8, b - 86, "CO₂", "tx2", "start");
      }
      if (o.palha) s += palha(x, b, o.palha);
      if (o.rot) s += D.txt(x, 16, o.rot, "tx2");
      return s;
    };
    /* tabela desenhada: larg = larguras das colunas; a primeira linha é o cabeçalho */
    const tab = (x, y, larg, linhas) => linhas.map((l, i) => l.map((c, j) => D.txt(x + larg.slice(0, j).reduce((a, b) => a + b, 0) + larg[j] / 2, y + i * 24, c, "tx2", "middle", i ? "" : 'style="font-weight:700;fill:var(--ink)"')).join("")).join("") + `<line x1="${x}" x2="${x + larg.reduce((a, b) => a + b, 0)}" y1="${y + 8}" y2="${y + 8}" style="stroke:var(--ink3)"/>`;
    const crono = (x, y, rot) => `<circle cx="${x}" cy="${y}" r="20" style="fill:var(--bg);stroke:var(--ink2);stroke-width:2"/><rect x="${x - 3}" y="${y - 27}" width="6" height="7" style="fill:var(--ink2)"/><line x1="${x}" y1="${y}" x2="${x + 9}" y2="${y - 10}" style="stroke:var(--bad);stroke-width:2"/>` + D.txt(x, y + 38, rot, "tx2");
    /* copo com comprimido borbulhando e termômetro */
    const copoT = (x, rotT, rot, quente, pedacos = 1) => D.copo(x - 32, 36, 64, 84, 0.62, quente ? "var(--bad)" : "var(--mA)") + Array.from({ length: pedacos }, (_, i) => `<ellipse cx="${x + (i - (pedacos - 1) / 2) * 13}" cy="114" rx="${pedacos > 1 ? 5 : 12}" ry="${pedacos > 1 ? 2.6 : 5}" style="fill:var(--ink)"/>`).join("") + [[-10, 96], [6, 84], [14, 100], [-3, 76]].map(([dx, y]) => `<circle cx="${x + dx}" cy="${y}" r="2.4" style="fill:none;stroke:var(--ink);stroke-width:1.1"/>`).join("") + D.termo(x + 52, 108, 66, quente ? 0.78 : 0.28, rotT, quente ? "var(--bad)" : "var(--mA)") + D.txt(x, 146, rot, "tx2");
    /* frasco selado sobre a chama, com o metal dentro */
    const retorta = (x, rot, o = {}) => `<circle cx="${x}" cy="88" r="38" style="fill:color-mix(in srgb,var(--mA) 10%,transparent);stroke:var(--ink2);stroke-width:2.2"/><rect x="${x - 9}" y="26" width="18" height="28" style="fill:var(--bg);stroke:var(--ink2);stroke-width:2.2"/>` + (o.aberto ? "" : `<rect x="${x - 12}" y="18" width="24" height="10" rx="3" style="fill:var(--ink3)"/>`) + `<ellipse cx="${x}" cy="118" rx="20" ry="5" style="fill:${o.cor || "var(--ink3)"}"/>` + (o.chama ? D.chama(x, 160, 1) : "") + D.txt(x, o.chama ? 10 : 150, rot, "tx2", "middle") + (o.ar ? D.txt(x, 84, o.ar, "tx2") : "");
    const mapaRamos = fig(`<rect x="220" y="64" width="120" height="40" rx="8" style="fill:color-mix(in srgb,var(--mod) 30%,transparent);stroke:var(--mod);stroke-width:2"/>` + D.txt(280, 89, "QUÍMICA", "tx", "middle", 'style="font-weight:700"') +
      [[20, 8, "inorgânica", "sais, ácidos, metais", 160, 50, 222, 70], [20, 118, "orgânica", "cadeias de carbono", 160, 122, 222, 100], [400, 8, "físico-química", "energia e velocidade", 400, 50, 338, 70], [400, 118, "analítica", "o quê e quanto", 400, 122, 338, 100], [210, 132, "bioquímica", "a química da vida", 280, 132, 280, 104]].map(([x, y, a, b, x1, y1, x2, y2]) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" style="stroke:var(--ink3);stroke-dasharray:3 3"/><rect x="${x}" y="${y}" width="140" height="42" rx="6" style="fill:var(--card2);stroke:var(--ink3)"/>` + D.txt(x + 70, y + 18, a, "tx2", "middle", 'style="font-weight:700;fill:var(--ink)"') + D.txt(x + 70, y + 35, b, "tx2")).join(""), 180);
    const ciclo = fig([["observar", 20, 20], ["perguntar", 210, 20], ["hipótese", 400, 20], ["experimento", 400, 110], ["analisar", 210, 110], ["concluir", 20, 110]].map(([t, x, y], i) => D.bloco(x, y, 140, 40, i === 2 || i === 3 ? "var(--mod)" : "var(--ink3)", t)).join("") + D.seta(162, 40, 208, 40, "var(--ink2)") + D.seta(352, 40, 398, 40, "var(--ink2)") + D.seta(470, 62, 470, 108, "var(--ink2)") + D.seta(398, 130, 352, 130, "var(--ink2)") + D.seta(208, 130, 162, 130, "var(--ink2)") + `<path d="M280 108 Q330 85 430 64" style="fill:none;stroke:var(--bad);stroke-width:1.8;stroke-dasharray:5 4"/>` + D.txt(272, 92, "não bateu? nova hipótese", "tx2", "end", 'style="fill:var(--bad)"'), 165);

    const exemplos = F.exemplo({
      titulo: "Do laboratório para a conta",
      casos: [
        { nome: "Fácil: variáveis, média e variação percentual", gerar: (p) => {
          const [a, b] = p ? [[62, 58, 60], [31, 29, 30]] : F.escolha([[[62, 58, 60], [31, 29, 30]], [[47, 50, 53], [39, 41, 40]], [[81, 78, 81], [58, 62, 60]]]), ma = (a[0] + a[1] + a[2]) / 3, mb = (b[0] + b[1] + b[2]) / 3, v = ((mb - ma) / ma) * 100;
          return { enun: R`<p>Para testar se a temperatura muda o tempo de dissolução de um comprimido efervescente, você usa sempre 200 mL de água e o comprimido inteiro, e cronometra três vezes em cada temperatura. A 20 °C: ${a.join(" s, ")} s. A 30 °C: ${b.join(" s, ")} s. Quais são as variáveis? De quantos por cento o tempo mudou?</p>`,
            fig: fig(copoT(120, "20 °C", "200 mL, inteiro", false) + copoT(330, "30 °C", "200 mL, inteiro", true) + crono(490, 70, "3 medidas em cada")),
            passos: [R`<p>(i) Variável <b>independente</b> (a que você escolhe mudar): a temperatura. Variável <b>dependente</b> (a que você mede): o tempo. Variáveis <b>controladas</b> (as que ficam iguais): volume de água, tipo e tamanho do comprimido, o copo, não mexer.</p>`,
              R`<p>(ii) Média de cada grupo: $\bar t_{20} = \frac{${a.join(" + ")}}{3} = ${F.n(ma)}$ s e $\bar t_{30} = \frac{${b.join(" + ")}}{3} = ${F.n(mb)}$ s.</p>`,
              R`<p>(iii) Variação percentual: $\frac{\bar t_{30} - \bar t_{20}}{\bar t_{20}} = \frac{${F.n(mb)} - ${F.n(ma)}}{${F.n(ma)}} = ${F.n(v / 100)}$, isto é, ${F.nt(v)}%.</p>`,
              R`<p>(iv) Dá para confiar? Dentro de cada grupo as medidas se espalham por ${Math.max(...a) - Math.min(...a)} s e ${Math.max(...b) - Math.min(...b)} s; a diferença entre as médias é de ${F.nt(ma - mb)} s, muito maior que esse espalhamento. Então a queda é um efeito de verdade, não o acaso do cronômetro: o tempo caiu ${F.nt(-v)}% com 10 °C a mais.</p>`] };
        } },
        { nome: "Médio: o mesmo experimento, aberto e fechado", gerar: (p) => {
          const n = p ? 1 : F.escolha([1, 2, 3]), g = p ? 0.52 : F.escolha([0.48, 0.5, 0.52]), m0 = p ? 254 : F.escolha([198.5, 254, 310]), mf = m0 - n * g, pl = n > 1 ? "s" : "";
          return { enun: R`<p>Dois frascos iguais, cada um com água e ${n} comprimido${pl} efervescente${pl} ainda no prato, marcam ${F.t(m0)} g na balança. No frasco A, você solta o${pl} comprimido${pl} e tampa na mesma hora com uma rolha que não deixa nada escapar. No B, solta e deixa aberto. Quando o borbulhar acaba, B marca ${F.t(mf)} g. (a) Quanto marca A? (b) Que massa de gás cada comprimido produziu?</p>`,
            fig: fig(balanca(150, "?", { tampa: true, bolhas: true, rot: "A: fechado" }) + balanca(400, F.t(mf) + " g", { bolhas: true, gas: true, rot: "B: aberto" })),
            passos: [R`<p>(i) Desenhe a fronteira do sistema. Em A, a fronteira é o frasco tampado: nada entra e nada sai. Em B, o gás atravessa a boca do frasco e vai para o ar da sala.</p>`,
              R`<p>(ii) Sistema fechado: a massa total não muda (Teorema 2). A continua marcando $${F.m(m0)}$ g, mesmo com a reação inteira acontecendo lá dentro.</p>`,
              R`<p>(iii) Sistema aberto: o que a balança perdeu é o gás que saiu. $m_\text{gás} = ${F.m(m0)} - ${F.m(mf)} = ${F.m(n * g)}$ g.</p>`,
              R`<p>(iv) ${n > 1 ? R`Por comprimido: $\frac{${F.m(n * g)}}{${n}} = ${F.m(g)}$ g.` : R`Como havia um comprimido só, são $${F.m(g)}$ g por comprimido.`} O gás é dióxido de carbono, $\ce{CO2}$: a massa dele não "sumiu", só saiu de cima da balança. No frasco A ela está lá, presa, empurrando a rolha.</p>`] };
        } },
        { nome: "Olimpíada: a palha de aço que engorda", gerar: (p) => {
          const [m, f] = p ? [5, 0.4] : F.escolha([[5, 0.4], [8, 0.25], [10, 0.5], [6, 0.5], [4, 0.5], [10, 0.2]]), O = 0.43 * f * m, M = m + O;
          return { enun: R`<p>Uma palha de aço (considere ferro puro) de ${F.t(m)} g é queimada ao ar, sobre o prato da balança. Depois de fria, o sólido marca ${F.t(M)} g. Sabe-se, de medidas cuidadosas, que cada 1,00 g de ferro que reage por completo prende 0,43 g de oxigênio. (a) O resultado combina com a ideia de que queimar é "perder flogisto"? (b) Que massa de ferro reagiu de fato? (c) O que a balança marcaria se a queima fosse feita dentro de um frasco selado?</p>`,
            fig: fig(balanca(150, F.t(m) + " g", { palha: "var(--ink2)", rot: "antes" }) + D.seta(235, 100, 315, 100, "var(--bad)") + D.chama(275, 92, 0.9) + balanca(400, F.t(M) + " g", { palha: "var(--bad)", rot: "depois" })),
            passos: [R`<p>(i) Se queimar fosse perder alguma coisa (o flogisto), o sólido ficaria mais leve. Ele ficou mais pesado: $${F.m(M)} - ${F.m(m)} = ${F.m(O)}$ g a mais. A hipótese do flogisto, com massa positiva, está refutada por esse número.</p>`,
              R`<p>(ii) Hipótese rival: o ferro <b>se junta</b> com algo do ar. Então o ganho é a massa de oxigênio preso: $m_\text{O} = ${F.m(O)}$ g.</p>`,
              R`<p>(iii) Proporção: 1,00 g de ferro prende 0,43 g de oxigênio. Então reagiram $\frac{${F.m(O)}}{0{,}43} = ${F.m(O / 0.43)}$ g de ferro.</p>`,
              R`<p>(iv) Isso é $\frac{${F.m(O / 0.43)}}{${F.m(m)}} = ${F.n(f * 100)}\%$ da palha. O resto não queimou: os fios de dentro ficam sem ar e esfriam antes de reagir.</p>`,
              R`<p>(v) Em frasco selado, a balança marcaria o mesmo valor antes e depois: o oxigênio que o ferro prende já estava dentro do frasco, do lado de dentro da fronteira. A reação é $\ce{4Fe + 3O2 -> 2Fe2O3}$: os átomos só mudam de companhia.</p>`] };
        } },
      ],
    });

    const chefao = F.chefao({
      titulo: "O frasco que mede quanto do ar serve para queimar",
      enun: R`<p>Você tem um frasco de vidro de 2,00 L com rolha perfeita, cheio de ar. Dados medidos à temperatura da sala: o ar tem 1,20 g por litro; o oxigênio é 23% da <b>massa</b> do ar; oxigênio puro tem 1,33 g por litro; cada 1,00 g de ferro que reage por completo prende 0,43 g de oxigênio. Você põe palha de aço (ferro) no frasco, fecha, pesa tudo (612,00 g), aquece até a palha queimar e espera esfriar até a temperatura da sala.</p>
        <p>(a) Com 1,00 g de palha, que queima inteira: quanto o sólido ganhou e quanto marca a balança com o frasco ainda fechado? (b) Você abre a rolha, ouve o ar entrar, fecha e pesa de novo. Quanto marca agora? Por que o ar que entrou não tem a mesma massa que o sólido ganhou? (c) Repita com 5,00 g de palha: que massa de ferro consegue reagir, no máximo, e que porcentagem da palha isso é? (d) Que fração do <b>volume</b> do ar foi consumida no item (c)? (e) Um defensor do flogisto responde: "o calor é que entra no metal e pesa". Desenhe um ensaio de controle que derrube essa saída, dizendo o que cada hipótese prevê. (f) Faça uma previsão arriscada: com 5,00 g de palha num frasco de 4,00 L, quanto o sólido ganha? O que você concluiria se medisse o mesmo ganho do frasco de 2,00 L?</p>`,
      fig: fig(retorta(130, "fechado, na chama", { chama: true, ar: "ar: 2,00 L" }) + D.seta(200, 90, 250, 90, "var(--ink2)") + retorta(310, "frio, fechado: 612,00 g", { cor: "var(--bad)" }) + D.seta(378, 90, 428, 90, "var(--ink2)") + retorta(480, "aberto: entra ar", { aberto: true, cor: "var(--bad)" }) + D.seta(480, 2, 480, 24, "var(--mA)", 2), 175),
      dicas: [R`<p>Antes de qualquer conta, ache quanto ar e quanto oxigênio existem dentro do frasco: massa = litros × gramas por litro; oxigênio = 23% disso.</p>`,
        R`<p>(b) O oxigênio que virou sólido deixou um "buraco" no ar do frasco. O ar de fora entra até preencher o mesmo <b>volume</b> que o oxigênio ocupava, não a mesma massa. Ache esse volume com o 1,33 g/L e encha de ar a 1,20 g/L.</p>`,
        R`<p>(c) Quem acaba primeiro: o ferro ou o oxigênio do frasco? (e) Um bom controle recebe o mesmo calor e só perde a coisa que você suspeita que seja a causa.</p>`],
      sol: R`<p><b>Preparação.</b> Ar no frasco: $2{,}00\cdot1{,}20 = 2{,}40$ g. Oxigênio disponível: $0{,}23\cdot2{,}40 = 0{,}552$ g.</p>
        <p><b>(a)</b> 1,00 g de ferro precisa de 0,43 g de oxigênio, e há 0,552 g: sobra oxigênio, a palha queima toda. O sólido ganha <b>0,43 g</b> (passa a 1,43 g). Com o frasco fechado, nada atravessou a fronteira: a balança continua em <b>612,00 g</b>.</p>
        <p><b>(b)</b> O oxigênio consumido ocupava $\frac{0{,}43}{1{,}33} = 0{,}323$ L. Ao abrir, entra ar até preencher esse volume: $0{,}323\cdot1{,}20 = 0{,}388$ g. A balança passa a marcar $612{,}00 + 0{,}39 = $ <b>612,39 g</b>. O ar que entra pesa menos que o oxigênio que saiu do ar (0,39 contra 0,43 g) porque, litro por litro, o ar é mais leve que o oxigênio puro. Nenhuma massa foi criada: o frasco ganhou exatamente o que atravessou a boca dele.</p>
        <p><b>(c)</b> Agora o ferro sobra e o oxigênio manda (é o que mais tarde vamos chamar de reagente limitante ${F.ret("D06")}). Ferro que reage: $\frac{0{,}552}{0{,}43} = 1{,}28$ g, isto é, $\frac{1{,}28}{5{,}00} = 25{,}7\%$ da palha. O sólido ganha 0,552 g e para aí, por mais que você aqueça.</p>
        <p><b>(d)</b> Volume de oxigênio consumido: $\frac{0{,}552}{1{,}33} = 0{,}415$ L, ou $\frac{0{,}415}{2{,}00} = 20{,}8\%$: cerca de <b>um quinto</b> do ar. O resto (quase todo nitrogênio) não serve para queimar. Foi com um experimento desse tipo que Lavoisier concluiu que só uma parte do ar participa da combustão.</p>
        <p><b>(e)</b> Controle: o mesmo frasco, a mesma palha, a mesma chama pelo mesmo tempo, mas sem oxigênio lá dentro (por exemplo, o ar "gasto" que sobrou do item (c), ou o frasco esvaziado com uma bomba). Hipótese do calor que pesa: o metal ganha massa do mesmo jeito, porque recebeu o mesmo calor. Hipótese do oxigênio: o metal não ganha nada. Além disso, a hipótese do calor prevê que a balança suba com o frasco fechado (o calor atravessa o vidro), e ela ficou em 612,00 g. Dois resultados independentes contra a mesma ideia.</p>
        <p><b>(f)</b> Dobro de ar, dobro de oxigênio: $0{,}23\cdot4{,}00\cdot1{,}20 = 1{,}104$ g, que dão conta de $\frac{1{,}104}{0{,}43} = 2{,}57$ g de ferro (51,3% da palha). Previsão: o sólido ganha <b>1,10 g</b>, o dobro de antes. Se o ganho medido fosse igual ao do frasco de 2,00 L, a hipótese "o ganho vem do ar do frasco" estaria em apuros, e você teria de procurar outra explicação (ou um vazamento, ou um erro de medida). É isso que faz dela uma boa hipótese: ela se arrisca. Contas conferidas em Python.</p>`,
    });

    const exs = [
      F.exercicio({ n: 1, nivel: "Físico", enun: R`<p>Uma pesquisadora mede quanto calor uma reação libera e como a velocidade dela muda com a temperatura. O trabalho dela está em qual ramo da química?</p>`, fig: mapaRamos, alts: ["Química orgânica.", "Química analítica.", "Química inorgânica.", "Bioquímica.", "Físico-química."], certa: "E", dicas: [R`<p>Olhe o mapa: qual ramo cuida de energia e de velocidade?</p>`], resp: "E", sol: R`<p>Energia das reações (termoquímica) e velocidade (cinética) são assuntos da físico-química, a fronteira entre a química e a física.</p>` }),
      F.exercicio({ n: 2, nivel: "Físico", enun: R`<p>Uma mineradora quer saber <b>quanto</b> ferro existe em cada tonelada de um minério. Esse problema é típico de qual ramo?</p>`, fig: fig(`<path d="M150 140 L200 60 L250 100 L300 40 L370 140 Z" style="fill:color-mix(in srgb,var(--bad) 25%,transparent);stroke:var(--ink3);stroke-width:2"/>` + D.txt(260, 160, "minério", "tx2") + D.seta(380, 90, 430, 90, "var(--ink2)") + D.txt(480, 95, "? % de ferro", "tx2"), 170), alts: ["Inorgânica, porque o ferro é um metal.", "Orgânica, porque o minério vem da natureza.", "Bioquímica.", "Analítica (análise quantitativa).", "Físico-química, porque envolve massa."], certa: "D", dicas: [R`<p>A pergunta não é "como o ferro reage", e sim "quanto tem".</p>`], resp: "D", sol: R`<p>Descobrir o que há numa amostra (análise qualitativa) e quanto há (quantitativa) é o trabalho da química analítica. O ferro é assunto da inorgânica, mas a <b>pergunta</b> é analítica: <b>A</b> confunde o material com o problema.</p>` }),
      F.exercicio({ n: 3, nivel: "Físico", enun: R`<p>No ensaio da figura, os dois copos têm o mesmo volume de água e o mesmo comprimido inteiro; só a temperatura muda, e mede-se o tempo de dissolução. Qual é a variável independente?</p>`, fig: fig(copoT(170, "10 °C", "200 mL, inteiro", false) + copoT(380, "40 °C", "200 mL, inteiro", true)), alts: ["O tempo de dissolução.", "O volume de água.", "A temperatura da água.", "O tamanho do comprimido.", "A marca do cronômetro."], certa: "C", dicas: [R`<p>Independente é a que <b>você</b> decide mudar de um ensaio para o outro.</p>`], resp: "C", sol: R`<p>Você escolhe a temperatura (independente) e mede o tempo (dependente, <b>A</b>). Volume e tamanho ficam iguais: são variáveis controladas.</p>` }),
      F.exercicio({ n: 4, nivel: "Físico", enun: R`<p>Qual das frases é uma hipótese científica, isto é, uma afirmação que um experimento poderia mostrar que está errada?</p>`, fig: ciclo, alts: ["A química é a ciência mais bonita.", "Com a mesma água, o comprimido triturado dissolve em menos tempo que o inteiro.", "Talvez alguma coisa influencie a dissolução.", "A dissolução acontece porque tem de acontecer.", "Forças que nenhum aparelho detecta empurram as bolhas."], certa: "B", dicas: [R`<p>Para cada frase, pergunte: que resultado de experimento me faria abandonar essa ideia?</p>`], resp: "B", sol: R`<p>Só <b>B</b> se arrisca: basta cronometrar e ver o triturado demorar mais para ela cair. <b>A</b> é gosto; <b>C</b> e <b>D</b> são vagas demais para falhar; <b>E</b> se protege de qualquer teste.</p>` }),
      F.exercicio({ n: 5, nivel: "Físico", enun: R`<p>Três cronometragens do mesmo ensaio deram 41 s, 44 s e 38 s. Qual valor você anota como resultado (a média)?</p>`, fig: fig(crono(170, 70, "41 s") + crono(280, 70, "44 s") + crono(390, 70, "38 s"), 130), num: { v: 41, un: "s" }, dicas: [R`<p>Some e divida pelo número de medidas.</p>`], resp: "41 s", sol: R`<p>$\frac{41 + 44 + 38}{3} = \frac{123}{3} = 41$ s. Nenhuma medida sozinha é "a certa": a média é a melhor estimativa ${F.ret("fisica/FE03")}.</p>` }),
      F.exercicio({ n: 6, nivel: "Físico", enun: R`<p>Um frasco aberto com água e um comprimido efervescente no prato marca 254,00 g. Depois de soltar o comprimido e o borbulhar acabar, marca 253,48 g. Que massa de gás saiu?</p>`, fig: fig(balanca(150, "254,00 g", { rot: "antes" }) + D.seta(235, 100, 315, 100, "var(--ink2)") + balanca(400, "253,48 g", { bolhas: true, gas: true, rot: "depois" })), num: { v: 0.52, un: "g" }, dicas: [R`<p>O frasco está aberto: o que a balança perdeu foi embora pela boca do frasco.</p>`], resp: "0,52 g", sol: R`<p>$254{,}00 - 253{,}48 = 0{,}52$ g de $\ce{CO2}$.</p>` }),
      F.exercicio({ n: 7, nivel: "Físico", enun: R`<p>O ensaio do exercício anterior é repetido com tudo igual, mas o frasco é tampado no instante em que o comprimido cai, e a rolha não deixa escapar nada. Quanto a balança marca no fim?</p>`, fig: fig(balanca(280, "?", { tampa: true, bolhas: true, rot: "fechado" })), alts: ["254,00 g", "253,48 g", "253,74 g", "254,52 g", "Menos de 253,48 g."], certa: "A", dicas: [R`<p>Onde está o gás agora? Do lado de dentro ou de fora da fronteira do sistema?</p>`], resp: "A", sol: R`<p>Sistema fechado: nada entra, nada sai, a massa total fica em 254,00 g. <b>D</b> soma o gás como se ele tivesse vindo de fora; <b>B</b> esquece a rolha.</p>` }),
      F.exercicio({ n: 8, nivel: "Físico", enun: R`<p>Para saber se sal na água muda o tempo de dissolução, um colega prepara três copos com 1, 2 e 3 colheres de sal e solta um comprimido em cada. O que falta para o experimento ficar bem desenhado?</p>`, fig: fig([1, 2, 3].map((k) => D.copo(60 + k * 110, 40, 60, 80, 0.6) + D.txt(90 + k * 110, 140, k + (k > 1 ? " colheres" : " colher"), "tx2")).join("") + `<path d="M60 40 L60 120 L120 120 L120 40" style="fill:none;stroke:var(--ink3);stroke-width:2;stroke-dasharray:5 4"/>` + D.txt(90, 85, "?", "tx") + D.txt(90, 140, "falta este", "tx2"), 155), alts: ["Um copo com 4 colheres de sal.", "Um copo sem sal, com todo o resto igual (o controle).", "Trocar a marca do comprimido em cada copo.", "Usar água mais quente nos copos com mais sal.", "Nada: três copos bastam."], certa: "B", dicas: [R`<p>Com que tempo você vai comparar os três resultados?</p>`], resp: "B", sol: R`<p>Sem o copo sem sal não há referência: você não sabe se 1 colher já mudou alguma coisa. <b>C</b> e <b>D</b> estragam o teste, porque mudam uma segunda variável junto.</p>` }),
      F.exercicio({ n: 9, nivel: "Máximo", enun: R`<p>Uma palha de aço de 8,00 g é queimada ao ar e passa a pesar 9,29 g. Cada 1,00 g de ferro que reage prende 0,43 g de oxigênio. Quantos gramas de ferro reagiram?</p>`, fig: fig(balanca(150, "8,00 g", { palha: "var(--ink2)", rot: "antes" }) + D.seta(235, 100, 315, 100, "var(--bad)") + D.chama(275, 92, 0.9) + balanca(400, "9,29 g", { palha: "var(--bad)", rot: "depois" })), num: { v: 3, un: "g" }, dicas: [R`<p>O ganho de massa é o oxigênio que o ferro prendeu.</p>`, R`<p>Regra de três: 0,43 g de oxigênio para cada 1,00 g de ferro.</p>`], resp: "3,00 g", sol: R`<p>Oxigênio preso: $9{,}29 - 8{,}00 = 1{,}29$ g. Ferro: $\frac{1{,}29}{0{,}43} = 3{,}00$ g (só 37,5% da palha queimou).</p>` }),
      F.exercicio({ n: 10, nivel: "Máximo", enun: R`<p>Com tudo o mais igual, o tempo de dissolução foi 80 s a 20 °C, 40 s a 30 °C e 20 s a 40 °C. Se o padrão continuar, qual o tempo a 50 °C?</p>`, fig: D.svg(560, 210, D.graf({ x0: 70, y0: 180, w: 400, h: 140, xmax: 60, ymin: 0, ymax: 90, xlab: "T (°C)", ylab: "tempo (s)", xt: [20, 30, 40, 50], yt: [20, 40, 80], curvas: [{ pts: D.amostra((x) => 80 * Math.pow(2, -(x - 20) / 10), 20, 40), cor: "var(--mod)" }], pontos: [[20, 80], [30, 40], [40, 20], [50, 3, "?"]] }), "gráfico"), num: { v: 10, un: "s" }, dicas: [R`<p>Teste as diferenças (80 − 40, 40 − 20) e depois as razões (80 ÷ 40, 40 ÷ 20). Qual das duas é constante?</p>`], resp: "10 s", sol: R`<p>As diferenças mudam (40, 20), as razões não: a cada 10 °C o tempo cai pela metade. A 50 °C: $\frac{20}{2} = 10$ s. Quem supõe queda de 20 s por degrau chega a 0 s, um absurdo.</p>` }),
      F.exercicio({ n: 11, nivel: "Máximo", enun: R`<p>O caderno de um colega tem só os dois ensaios da tabela. O que ele pode concluir?</p>`, fig: fig(tab(90, 40, [80, 110, 110, 90], [["ensaio", "temperatura", "comprimido", "tempo"], ["1", "20 °C", "inteiro", "80 s"], ["2", "40 °C", "triturado", "12 s"]]), 110), alts: ["Que só a temperatura importa.", "Que só triturar importa.", "Que a temperatura importa mais que triturar.", "Nada sobre cada variável em separado: faltam ensaios que mudem uma de cada vez.", "Que o tempo é inversamente proporcional à temperatura."], certa: "D", dicas: [R`<p>Do ensaio 1 para o 2, quantas coisas mudaram?</p>`], resp: "D", sol: R`<p>Mudaram duas variáveis ao mesmo tempo, então o efeito de cada uma está misturado. Faltam, pelo menos, 40 °C com o inteiro e 20 °C com o triturado.</p>` }),
      F.exercicio({ n: 12, nivel: "Máximo", enun: R`<p>Ao trocar o comprimido inteiro por um partido em 4, o tempo médio caiu de 60 s para 45 s. De quantos por cento foi a queda?</p>`, fig: fig(copoT(150, "25 °C", "inteiro: 60 s", false, 1) + copoT(370, "25 °C", "4 pedaços: 45 s", false, 4)), num: { v: 25, un: "%" }, dicas: [R`<p>Variação percentual: divida a variação pelo valor <b>inicial</b>.</p>`], resp: "25%", sol: R`<p>$\frac{45 - 60}{60} = -0{,}25$: queda de 25%. Dividir por 45 (dando 33%) é o erro clássico: a base é sempre o valor de partida.</p>` }),
      F.exercicio({ n: 13, nivel: "Máximo", enun: R`<p>"Em um sistema fechado, a massa total é a mesma antes e depois de qualquer reação química." Essa frase é um exemplo de:</p>`, fig: fig(balanca(150, "500,00 g", { tampa: true, rot: "antes" }) + D.txt(275, 100, "=", "tx") + balanca(400, "500,00 g", { tampa: true, bolhas: true, cor: "var(--warn)", rot: "depois" })), alts: ["hipótese, porque ainda não foi testada.", "teoria, porque explica por que a massa se conserva.", "lei, porque resume uma regularidade observada, sem explicar a causa.", "modelo, porque é um desenho simplificado.", "observação isolada."], certa: "C", dicas: [R`<p>A frase diz <b>o que</b> acontece ou <b>por que</b> acontece?</p>`], resp: "C", sol: R`<p>É a lei de Lavoisier: descreve o que sempre se observa. A explicação (os átomos só se rearranjam, não surgem nem somem) pertence à teoria atômica ${F.ret("D03")}.</p>` }),
      F.exercicio({ n: 14, nivel: "Máximo", enun: R`<p>Estanho é aquecido num frasco selado. O frasco inteiro pesa 500,00 g antes e 500,00 g depois. Aberto o frasco, o metal é pesado sozinho: tinha 20,00 g e agora tem 20,35 g. Que massa do gás de dentro do frasco o metal prendeu?</p>`, fig: fig(retorta(170, "selado: 500,00 g", { chama: true }) + D.seta(250, 90, 310, 90, "var(--ink2)") + balanca(400, "20,35 g", { frasco: false, rot: "o metal, depois" }) + `<ellipse cx="400" cy="122" rx="22" ry="6" style="fill:var(--ink3)"/>`, 175), num: { v: 0.35, un: "g" }, dicas: [R`<p>A massa total não mudou. Então o que o metal ganhou veio de onde?</p>`], resp: "0,35 g", sol: R`<p>$20{,}35 - 20{,}00 = 0{,}35$ g. Como o total ficou em 500,00 g, o ar de dentro perdeu exatamente esses 0,35 g: a massa só mudou de lugar, do gás para o sólido.</p>` }),
      F.exercicio({ n: 15, nivel: "Máximo", enun: R`<p>Em frasco aberto, 1 comprimido soltou 0,50 g de gás e 3 comprimidos soltaram 1,50 g. Um frasco aberto com água e 5 comprimidos no prato marca 320,00 g. Quanto marcará depois que os 5 se dissolverem?</p>`, fig: D.svg(560, 200, D.graf({ x0: 70, y0: 170, w: 400, h: 130, xmax: 7, ymin: 0, ymax: 3, xlab: "comprimidos", ylab: "gás (g)", xt: [1, 2, 3, 4, 5], yt: [0.5, 1.5], curvas: [{ pts: [[0, 0], [3, 1.5]], cor: "var(--mod)" }, { pts: [[3, 1.5], [5, 2.5]], cor: "var(--mod)", trac: true }], pontos: [[1, 0.5], [3, 1.5], [5, 2.5, "?"]] }), "gráfico"), num: { v: 317.5, tol: 0.0005, un: "g" }, dicas: [R`<p>O gás é proporcional ao número de comprimidos: a razão gás ÷ comprimidos é constante.</p>`, R`<p>Ache o gás de 5 comprimidos e desconte da leitura.</p>`], resp: "317,50 g", sol: R`<p>$\frac{0{,}50}{1} = \frac{1{,}50}{3} = 0{,}50$ g por comprimido. Cinco soltam 2,50 g: $320{,}00 - 2{,}50 = 317{,}50$ g.</p>` }),
      F.exercicio({ n: 16, nivel: "Máximo", enun: R`<p>A teoria do flogisto dizia que queimar é perder flogisto, uma substância com massa. Qual par de observações ela <b>não</b> consegue explicar?</p>`, fig: fig(balanca(110, "sobe", { palha: "var(--bad)", rot: "metal calcinado ao ar" }) + balanca(280, "desce", { frasco: false, rot: "carvão queimado ao ar" }) + `<path d="M262 126 l10 -12 l12 6 l10 -8 l6 14 Z" style="fill:var(--ink3)"/>` + balanca(450, "igual", { tampa: true, cor: "var(--warn)", rot: "frasco selado" })), alts: ["O carvão fica mais leve ao queimar, e sobra pouca cinza.", "A madeira queima melhor quando está seca.", "A vela apaga dentro de um pote fechado.", "Metais brilham e a cal de metal (o óxido) é opaca.", "O metal calcinado ao ar fica mais pesado, e em frasco selado a massa total não muda."], certa: "E", dicas: [R`<p>O que a teoria prevê para a massa de qualquer coisa que queima?</p>`], resp: "E", sol: R`<p>Perder algo com massa deveria deixar o metal mais leve, e ele fica mais pesado. No frasco selado o total não muda, mas o metal lá dentro continua ganhando massa: esse ganho só pode ter vindo do ar preso no frasco, não de uma perda. <b>A</b> e <b>C</b> a teoria explicava bem (o flogisto saiu; o ar "saturou" de flogisto): por isso ela durou quase um século.</p>` }),
      F.exercicio({ n: 17, nivel: "Máximo", enun: R`<p>Uma palha de aço de 6,00 g, queimada ao ar, passa a 6,645 g. Com 0,43 g de oxigênio preso por grama de ferro que reage, que porcentagem da palha reagiu?</p>`, fig: fig(balanca(150, "6,00 g", { palha: "var(--ink2)", rot: "antes" }) + D.seta(235, 100, 315, 100, "var(--bad)") + D.chama(275, 92, 0.9) + balanca(400, "6,645 g", { palha: "var(--bad)", rot: "depois" })), num: { v: 25, un: "%" }, dicas: [R`<p>Ganho = oxigênio preso. Depois, ferro que reagiu = ganho ÷ 0,43.</p>`, R`<p>Compare o ferro que reagiu com os 6,00 g do começo.</p>`], resp: "25%", sol: R`<p>Oxigênio: $6{,}645 - 6{,}00 = 0{,}645$ g. Ferro: $\frac{0{,}645}{0{,}43} = 1{,}50$ g. Fração: $\frac{1{,}50}{6{,}00} = 25\%$.</p>` }),
      F.exercicio({ n: 18, nivel: "Máximo", enun: R`<p>Um pedaço de carvão (carbono) de 3,00 g queima por completo num frasco selado que tem oxigênio de sobra. Sabe-se que 3,00 g de carbono consomem 8,00 g de oxigênio, e que o único produto é o gás $\ce{CO2}$. Que massa de $\ce{CO2}$ se forma?</p>`, fig: fig(retorta(180, "antes: carvão + oxigênio", { cor: "var(--ink)", ar: "O₂" }) + D.seta(260, 90, 320, 90, "var(--bad)") + retorta(400, "depois: só gás (sobrou O₂)", { cor: "transparent", ar: "CO₂ + O₂" }), 165), num: { v: 11, un: "g" }, dicas: [R`<p>Sistema fechado: a massa do que reagiu é igual à massa do que se formou.</p>`], resp: "11,00 g", sol: R`<p>$m_{\ce{CO2}} = 3{,}00 + 8{,}00 = 11{,}00$ g. O carvão "sumiu" da vista, mas cada grama dele está no gás: ao ar livre a balança desce porque esse gás vai embora, não porque a massa deixou de existir.</p>` }),
    ];

    return [
      F.secao("abertura", "Pergunta", R`<div class="abertura"><div class="det">Introdução à química · o que é e como se faz</div>
        <div class="q">Você queima uma palha de aço em cima da balança. Depois de fria, ela pesa mais, menos ou a mesma coisa?</div>
        <p>Quase todo mundo erra, e por quase cem anos os químicos também erraram. A resposta só apareceu quando alguém parou de discutir e passou a <b>pesar</b>. Este tema é sobre isso: o que a química estuda e qual é o jeito de perguntar que faz a natureza responder.</p></div>
        ${F.chute({ q: "a palha de aço queimada ao ar, depois de fria, fica…", ops: ["mais leve, porque parte dela virou fumaça.", "mais pesada.", "com a mesma massa.", "mais leve, porque o fogo consome matéria."], certa: 1, exp: "Mais pesada. O ferro não perde nada: ele se junta com o oxigênio do ar e vira óxido de ferro, um sólido. O ganho na balança é exatamente a massa de oxigênio que ficou presa. A madeira e o carvão ficam mais leves porque os produtos deles são gases, que vão embora." })}`),

      F.secao("quimica", "O que a química estuda", R`
        <p>A química é a ciência da <b>matéria e das suas transformações</b>. Diante de qualquer material, o químico faz quatro perguntas:</p>
        <table class="tb"><tr><th>Pergunta</th><th>Nome</th><th>Exemplo com a água</th></tr>
          <tr><td>Do que é feito?</td><td><b>composição</b></td><td>hidrogênio e oxigênio, 2 para 1: $\ce{H2O}$</td></tr>
          <tr><td>Como os átomos estão arrumados?</td><td><b>estrutura</b></td><td>molécula em V, com o oxigênio no meio</td></tr>
          <tr><td>Como se comporta?</td><td><b>propriedades</b></td><td>ferve a 100 °C (ao nível do mar), dissolve sal</td></tr>
          <tr><td>No que pode virar, e com que energia?</td><td><b>transformações</b></td><td>com corrente elétrica, vira $\ce{H2}$ e $\ce{O2}$</td></tr></table>
        <p>O fio que liga as quatro: <b>a estrutura explica as propriedades</b>. A molécula em V é a razão de a água dissolver sal; a arrumação dos átomos de carbono é a razão de o diamante riscar vidro e o grafite sujar o dedo. Quase tudo o que você vai estudar daqui para a frente é essa frase aplicada a um caso novo.</p>
        ${F.caixa("fisico", R`<p><b>Três andares.</b> O químico pensa em três níveis ao mesmo tempo. O <b>macroscópico</b> é o que se vê e se mede: a palha ficou escura e 0,86 g mais pesada. O <b>microscópico</b> é o que se imagina: átomos de ferro se ligando a átomos de oxigênio. O <b>simbólico</b> é o que se escreve: $\ce{4Fe + 3O2 -> 2Fe2O3}$. Errar em química é, quase sempre, perder a ligação entre dois andares. A cada problema, pergunte: o que eu veria? O que os átomos estão fazendo? Como eu escrevo isso?</p>`, "Pense como químico")}
        <h3>Os ramos</h3>
        ${F.fig(mapaRamos, "Os cinco ramos clássicos. As fronteiras são convenção: um problema real costuma atravessar vários.")}
        <table class="tb"><tr><th>Ramo</th><th>Pergunta típica</th><th>Onde aparece neste site</th></tr>
          <tr><td><b>Inorgânica</b></td><td>Como se comportam os elementos e seus compostos (sais, ácidos, bases, óxidos, metais)?</td><td>módulos B, C e D</td></tr>
          <tr><td><b>Orgânica</b></td><td>Como o carbono monta cadeias, e como elas reagem?</td><td>módulo H</td></tr>
          <tr><td><b>Físico-química</b></td><td>Quanta energia? Com que velocidade? Até onde a reação vai?</td><td>módulos E, F e G</td></tr>
          <tr><td><b>Analítica</b></td><td>O que há nesta amostra (qualitativa) e quanto há (quantitativa)?</td><td>módulo J</td></tr>
          <tr><td><b>Bioquímica</b></td><td>Como funcionam as moléculas dos seres vivos?</td><td>módulo I</td></tr></table>
        <p>Além desses, existem áreas de fronteira com nome próprio: química ambiental, nuclear, de materiais, de alimentos, farmacêutica. Repare que o ramo é definido pela <b>pergunta</b>, não pelo material: medir quanto ferro há num minério é química analítica, ainda que o ferro seja assunto da inorgânica.</p>`),

      F.secao("metodo", "O método científico", R`
        <p>Não existe uma receita única que todo cientista segue, mas existe um ciclo que se repete em toda descoberta séria:</p>
        ${F.fig(ciclo, "O ciclo. A seta tracejada é a mais importante: quando o experimento contraria a hipótese, quem cai é a hipótese.")}
        <p><b>Observar</b>: a palha queimada ficou mais pesada. <b>Perguntar</b>: de onde veio essa massa? <b>Hipótese</b>: veio do ar. <b>Experimento</b>: queimar num frasco selado, onde o ar não pode entrar. <b>Analisar</b>: a balança mudou? <b>Concluir</b>, e contar para os outros de um jeito que eles possam repetir.</p>
        <p>Uma hipótese só serve se for <b>falseável</b>: precisa proibir algum resultado. "O ganho de massa vem do ar do frasco" proíbe muita coisa: proíbe que a balança mude com o frasco fechado, proíbe que o metal ganhe massa num frasco sem ar, proíbe que o ganho seja o mesmo em frascos de tamanhos diferentes. Cada proibição é um experimento possível. Já "o fogo tem um princípio sutil que age de modo misterioso" não proíbe nada, e por isso não ensina nada.</p>
        <table class="tb"><tr><th>Palavra</th><th>O que é</th><th>Exemplo</th></tr>
          <tr><td><b>Observação</b></td><td>um fato medido</td><td>esta palha passou de 5,00 g para 5,86 g</td></tr>
          <tr><td><b>Hipótese</b></td><td>explicação provisória, que se arrisca</td><td>o ganho é ar que ficou preso no metal</td></tr>
          <tr><td><b>Lei</b></td><td>resumo de uma regularidade: diz <b>o que</b> acontece</td><td>em sistema fechado, a massa total não muda</td></tr>
          <tr><td><b>Teoria</b></td><td>explicação ampla e muito testada: diz <b>por que</b> acontece</td><td>a matéria é feita de átomos, que só se rearranjam</td></tr>
          <tr><td><b>Modelo</b></td><td>representação simplificada, boa dentro de um limite</td><td>átomo como bolinha; gás ideal</td></tr></table>
        ${F.caixa("pegadinha", R`<p><b>Teoria não é "lei que ainda não foi provada", e lei não é "teoria promovida".</b> São coisas diferentes: a lei descreve, a teoria explica. A teoria atômica nunca vai "virar lei", por mais confirmada que seja. E nenhuma das duas é provada para sempre: as duas valem enquanto sobreviverem aos testes. No dia a dia, "teoria" quer dizer palpite; em ciência, quer dizer o contrário.</p>`)}
        ${F.chute({ q: "com a mesma água, à mesma temperatura, um comprimido efervescente triturado some…", ops: ["no mesmo tempo que o inteiro, porque a massa é a mesma.", "mais devagar, porque o pó se espalha.", "mais depressa.", "depende só do volume de água."], certa: 2, exp: "Mais depressa. A reação acontece na superfície que toca a água, e triturar multiplica a superfície sem mudar a massa. Confira no laboratório abaixo, mudando só o comprimido e deixando o resto igual." })}`),

      F.secao("controle", "Experimento controlado", R`
        <p>O coração do método é o <b>teste justo</b>: para saber se uma coisa causa outra, mude <b>só ela</b> e mantenha todo o resto igual.</p>
        <table class="tb"><tr><th>Variável</th><th>O que você faz com ela</th><th>No comprimido efervescente</th></tr>
          <tr><td><b>independente</b></td><td>escolhe e muda de propósito</td><td>a temperatura da água</td></tr>
          <tr><td><b>dependente</b></td><td>mede</td><td>o tempo até o comprimido sumir</td></tr>
          <tr><td><b>controladas</b></td><td>mantém iguais em todos os ensaios</td><td>volume de água, comprimido inteiro, mesmo copo, sem mexer</td></tr></table>
        <p>O ensaio que serve de referência, sem o tratamento que você quer testar, chama-se <b>controle</b>. Sem ele não há com o que comparar.</p>
        <div id="lab-eferv"></div>
        <h3>Uma medida só não é resultado</h3>
        <p>Repita o mesmo ensaio no laboratório acima e os tempos saem diferentes: 59,6 s, 60,3 s, 60,1 s. Isso não é defeito, é o normal de toda medida ${F.ret("fisica/FE01")}. Por isso se repete e se tira a média:</p>
        ${F.formula(R`\bar x = \frac{x_1 + x_2 + \dots + x_n}{n}`, "Média de n repetições")}
        <p>E, para dizer de quanto uma grandeza mudou entre dois ensaios, usa-se a variação relativa ao valor de partida:</p>
        ${F.formula(R`\text{variação percentual} = \frac{x_\text{final} - x_\text{inicial}}{x_\text{inicial}}\times 100\%`, "Variação percentual (a base é sempre o valor inicial)")}
        <p>Uma diferença entre dois grupos só é um efeito de verdade se for bem maior que o espalhamento das medidas dentro de cada grupo. Se três repetições a 20 °C variam 4 s entre si e a média a 30 °C é 30 s menor, você achou um efeito. Se fosse 2 s menor, não achou nada.</p>
        <h3>Teorema 1: como achar a regra escondida numa tabela</h3>
        <p>Você mediu, com o resto controlado, 80 s a 20 °C, 40 s a 30 °C e 20 s a 40 °C. Que regra liga o tempo à temperatura?</p>
        ${F.demo("os três testes", R`<p>(i) <b>Teste da razão $\frac yx$</b>: se $y$ é diretamente proporcional a $x$, então $\frac yx$ é constante. Aqui: $\frac{80}{20} = 4$; $\frac{40}{30} = 1{,}33$; $\frac{20}{40} = 0{,}5$. Não é constante: não é proporção direta.</p>
          <p>(ii) <b>Teste do produto $y\cdot x$</b>: se $y$ é inversamente proporcional a $x$, o produto é constante. Aqui: $80\cdot20 = 1600$; $40\cdot30 = 1200$; $20\cdot40 = 800$. Também não.</p>
          <p>(iii) <b>Teste dos degraus iguais</b>: os valores de $x$ sobem de 10 em 10. Olhe o que acontece com $y$ a cada degrau. Diferenças: $40 - 80 = -40$ e $20 - 40 = -20$ (não constantes: não é reta). Razões: $\frac{40}{80} = \frac12$ e $\frac{20}{40} = \frac12$ (constantes!).</p>
          <p>(iv) Razão constante a cada degrau igual quer dizer: a cada 10 °C, o tempo é multiplicado por $\frac12$. Depois de $k$ degraus, $t = 80\cdot\left(\frac12\right)^k$ s, com $k = \frac{T - 20}{10}$. Previsão para 50 °C ($k = 3$): $80\cdot\frac18 = 10$ s. Agora é só medir e ver se a regra sobrevive.</p>`)}
        ${F.formula(R`y \propto x \iff \frac{y}{x} = \text{constante};\qquad y \propto \frac1x \iff y\cdot x = \text{constante}`, "Testes de proporcionalidade numa tabela")}
        <p>A regra "a velocidade de muitas reações mais ou menos dobra a cada 10 °C" é uma regra prática antiga, boa perto da temperatura ambiente e nada mais que isso; a explicação de verdade vem com a energia de ativação ${F.ret("F04")}.</p>
        ${F.caixa("pegadinha", R`<p><b>Duas coisas mudadas, nenhuma conclusão.</b> Se do ensaio 1 para o 2 você esquentou a água <b>e</b> triturou o comprimido, o tempo caiu, mas você não sabe por causa de quê. Pior: os efeitos podem até se cancelar e parecer que nada importa. E cuidado com a ordem das palavras: "andam juntos" não é "um causa o outro". Só o experimento controlado separa as duas coisas.</p>`)}
        ${F.caixa("pegadinha", R`<p><b>Em casa:</b> o ensaio do comprimido efervescente pode ser feito na cozinha, com copo, água, termômetro de cozinha e o cronômetro do celular. <b>Nunca feche o comprimido num recipiente rígido bem tampado</b> (garrafa com tampa de rosca, pote de vidro): a pressão do gás pode estourar o recipiente ou arremessar a tampa. Para ver o "sistema fechado", prenda um balão de festa na boca de uma garrafa PET, que estica em vez de estourar. Não beba o que sobrou se você misturou outra coisa; o resto vai para a pia, com água corrente. <b>Só no laboratório da escola, com o professor:</b> queimar palha de aço. Solta faíscas e o resíduo fica muito quente: óculos de segurança, cabelo preso, pinça metálica, bandeja de cerâmica ou de metal, nada inflamável por perto. Depois de frio, o resíduo (óxido de ferro) vai para o lixo comum.</p>`, "Segurança e descarte")}`),

      F.secao("massa", "A balança decide: sistema aberto e sistema fechado", R`
        <p><b>Sistema</b> é o pedaço do mundo que você escolheu estudar; o resto é a vizinhança. A linha entre os dois é a <b>fronteira</b>. Em química, a primeira pergunta sobre qualquer experimento com balança é: a matéria consegue atravessar a fronteira?</p>
        <ul><li><b>Sistema fechado</b>: nenhuma matéria entra nem sai (frasco bem tampado). A energia pode passar: o frasco esquenta e esfria.</li>
          <li><b>Sistema aberto</b>: matéria atravessa (copo sem tampa, palha queimando ao ar).</li></ul>
        ${F.fig(fig(balanca(150, "254,00 g", { tampa: true, bolhas: true, rot: "fechado: a leitura não muda" }) + balanca(400, "253,48 g", { bolhas: true, gas: true, rot: "aberto: perdeu o gás que saiu" })), "O mesmo comprimido, a mesma água, duas fronteiras diferentes.")}
        <h3>Teorema 2: o que a balança mostra</h3>
        ${F.demo("contabilidade da massa", R`<p>(i) Fato experimental (lei de Lavoisier): numa reação química, a massa dos produtos formados é igual à massa dos reagentes consumidos. Reação nenhuma cria ou destrói massa mensurável.</p>
          <p>(ii) Então a massa de dentro da fronteira só pode mudar por um motivo: matéria atravessando a fronteira. É uma conta de extrato bancário: saldo final = saldo inicial + o que entrou − o que saiu.</p>
          <p>(iii) Se a fronteira é fechada, entrou zero e saiu zero: $m_\text{final} = m_\text{inicial}$, por mais violenta que seja a reação lá dentro.</p>
          <p>(iv) Se é aberta: $\Delta m = m_\text{entrou} - m_\text{saiu}$. Comprimido efervescente: não entra nada e sai $\ce{CO2}$, então $\Delta m$ é negativo (254,00 → 253,48 g: saíram 0,52 g). Palha de aço: entra oxigênio e não sai nada, então $\Delta m$ é positivo (5,00 → 5,86 g: entraram 0,86 g).</p>`)}
        ${F.formula(R`m_\text{reagentes consumidos} = m_\text{produtos formados}`, "Lei de Lavoisier (conservação da massa)")}
        ${F.formula(R`\Delta m_\text{balança} = m_\text{entrou} - m_\text{saiu}\qquad(\text{sistema fechado: } \Delta m = 0)`, "O que a balança mostra")}
        <h3>Teorema 3: do ganho de massa à quantidade que reagiu</h3>
        <p>Medidas cuidadosas mostram que o ferro e o oxigênio sempre se juntam na mesma proporção quando formam o óxido $\ce{Fe2O3}$: 0,43 g de oxigênio para cada 1,00 g de ferro. (Proporção fixa é outra lei, a de Proust ${F.ret("D03")}.)</p>
        ${F.demo("palha de 5,00 g que passou a 5,86 g", R`<p>(i) Sistema aberto, nada sai: $\Delta m = m_\text{entrou}$. Oxigênio preso: $5{,}86 - 5{,}00 = 0{,}86$ g.</p>
          <p>(ii) Regra de três com a proporção fixa: se 0,43 g de oxigênio correspondem a 1,00 g de ferro, então 0,86 g correspondem a $\frac{0{,}86}{0{,}43} = 2{,}00$ g de ferro.</p>
          <p>(iii) Fração que reagiu: $\frac{2{,}00}{5{,}00} = 40\%$. A balança, sozinha, contou quanto ferro queimou, sem ninguém enxergar um átomo.</p>`)}
        ${F.formula(R`m_\text{Fe que reagiu} = \frac{\Delta m}{0{,}43}\qquad(\ce{4Fe + 3O2 -> 2Fe2O3})`, "Palha de aço queimada ao ar")}
        ${F.caixa("fisico", R`<p><b>Antes da conta, desenhe a fronteira.</b> "A massa sumiu" e "a massa apareceu" são sempre a mesma história: alguma coisa atravessou a linha que você não desenhou. O gás é o suspeito de sempre, porque ninguém o vê entrar nem sair. Num problema de balança, liste primeiro quem é gás.</p>`, "Pense como químico")}`),

      F.secao("lavoisier", "Lavoisier contra o flogisto", R`
        <p>No começo do século XVIII, a explicação aceita para o fogo era a <b>teoria do flogisto</b>, de Georg Stahl: tudo o que queima contém flogisto e o solta ao queimar. Era uma boa teoria para a época. Explicava por que o carvão quase desaparece (era quase só flogisto), por que a vela apaga num pote fechado (o ar fica "saturado" de flogisto) e por que a cal de um metal volta a ser metal quando aquecida com carvão (o carvão devolve o flogisto).</p>
        <p>Só havia um número teimoso: metais calcinados ao ar ficam <b>mais pesados</b>. Quem perde alguma coisa deveria ficar mais leve. Alguns defensores chegaram a propor que o flogisto tivesse peso negativo, um remendo que salvava a teoria ao preço de ela não proibir mais nada.</p>
        ${F.fig(fig(retorta(110, "metal em frasco selado", { chama: true, ar: "ar" }) + D.seta(180, 90, 230, 90, "var(--ink2)") + retorta(290, "frio: mesma massa total", { cor: "var(--bad)", ar: "menos ar" }) + D.seta(360, 90, 410, 90, "var(--ink2)") + retorta(470, "aberto: o ar entra", { aberto: true, cor: "var(--bad)" }) + D.seta(470, 2, 470, 24, "var(--mA)", 2), 175), "O experimento do frasco selado: a balança não se mexe enquanto a rolha está no lugar.")}
        <p>Na década de 1770, Antoine Lavoisier fez do frasco selado e da balança o centro da questão. Aqueceu metais (estanho, e depois mercúrio) em recipientes fechados e pesou tudo antes e depois: a massa total não mudava. Ao abrir, o ar entrava assobiando, sinal de que parte do ar de dentro tinha sido consumida; e o metal calcinado estava mais pesado. Conclusão: o metal não perde nada, ele <b>prende uma parte do ar</b>. Joseph Priestley tinha isolado esse gás em 1774 (Carl Scheele também, alguns anos antes, mas publicou depois); Lavoisier deu-lhe o nome de oxigênio e mostrou que ele é cerca de um quinto do ar. Em 1789 publicou o seu tratado de química com a conservação da massa como princípio de trabalho.</p>
        <p>Duas décadas antes, em 1756, o russo Mikhail Lomonosov já tinha calcinado metais em frascos selados e anotado que, sem a entrada de ar de fora, o peso não mudava. Por isso, em muitos livros (e nas provas russas), a lei aparece como lei de Lomonosov–Lavoisier.</p>
        ${F.caixa("olimpiada", R`<p><b>Como isso é cobrado.</b> Provas de olimpíada de química e vestibulares difíceis gostam de dar uma tabela ou um gráfico de um experimento que você nunca viu e pedir três coisas: identificar as variáveis e o controle, achar a regra dos dados (os três testes do Teorema 1) e dizer qual hipótese os dados derrubam. Em questões de balança, a pegadinha quase sempre é o gás que entrou ou saiu sem ser mencionado: palha de aço, magnésio e cobre <b>ganham</b> massa ao ar; carvão, vela, papel e comprimido efervescente <b>perdem</b>. Em prova discursiva, não basta o número: escreva a fronteira do sistema e a frase "em sistema fechado a massa se conserva" antes da conta.</p>`)}
        ${F.caixa("ponte", R`<p><b>Na universidade</b>, três coisas daqui ganham forma rigorosa. (1) "A diferença é maior que o espalhamento" vira um teste estatístico de hipótese, com desvio padrão e incerteza da média ${F.ret("fisica/FE03")}. (2) "Falseável" é o critério que o filósofo Karl Popper propôs para separar ciência do resto. (3) A conservação da massa, a rigor, é aproximada: pela relação $E = mc^2$ de Einstein, uma reação que libera energia perde um pouquinho de massa. Queimar 12 g de carbono libera 393,5 kJ, o que dá $\Delta m = \frac{E}{c^2} \approx 4\times10^{-12}$ kg: 4 nanogramas em 44 g de $\ce{CO2}$, muito abaixo do que qualquer balança de laboratório enxerga. Para a química, a lei de Lavoisier vale. Para reações nucleares, não ${F.ret("B08")}.</p>`)}`),

      F.secao("exemplos", "Exemplos resolvidos", exemplos),

      F.secao("desafios", "Exercícios", exs.join("") + chefao),
    ].join("");
  },
  montar(F) { const e = document.getElementById("lab-eferv"); e.outerHTML = F.lab("Experimento controlado: o comprimido efervescente", "lab-eferv"); SIM.efervescente(document.getElementById("lab-eferv"), F); },
});
